def hubs_index():
    return [
        {"slug": p["path"].strip("/"), "href": p["path"], "title": p["heading"], "summary": p["summary"],
         "category": p["category"], "aliases": p["aliases"], "status": p["status"]}
        for p in HUBS
    ]

def _sources(hub):
    return "".join(
        '<a href="'+h(url, quote=True)+'" target="_blank" rel="noopener noreferrer">'+h(url.split("/")[2])+' / source ↗</a>'
        for url in hub["sources"]
    )

def _faq(hub):
    return "".join(
        '<details class="faq"><summary>'+h(q)+'</summary><p>'+h(a)+'</p></details>'
        for q, a in hub["faq"]
    )

def hub_views(site_url):
    for hub in HUBS:
        url=site_url+hub["path"]
        faq=[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in hub["faq"]]
        ld=[
            {"@type":"Article","headline":hub["heading"],"description":hub["summary"],"datePublished":LAST_REVIEW,
             "dateModified":LAST_REVIEW,"author":{"@type":"Organization","name":"GTASIX Editorial"},
             "citation":hub["sources"],"about":{"@type":"VideoGame","name":"Grand Theft Auto VI"}},
            {"@type":"FAQPage","mainEntity":faq},
            {"@type":"BreadcrumbList","itemListElement":[
                {"@type":"ListItem","position":1,"name":"Home","item":site_url+"/"},
                {"@type":"ListItem","position":2,"name":hub["heading"],"item":url}
            ]}
        ]
        body=(
            '<section class="page-intro"><div class="wrap"><div class="crumb"><a href="/">HOME</a>'
            ' / <a href="/guides/">GUIDES</a> / '+h(hub["heading"])+'</div>'
            '<h1>'+h(hub["heading"])+'</h1><p class="lead">'+h(hub["summary"])+'</p></div></section>'
            '<main class="wrap intent-main">'+hub["body"]+
            '<section class="intent-panel"><h2>Frequently asked questions</h2><div class="faqs">'+_faq(hub)+'</div></section>'+
            '<section class="intent-panel"><h2>Sources and editorial verification</h2><p>Official sources take precedence over rumors. '
            'Last reviewed November 20, 2026. New announcements or updates can change these answers.</p>'
            '<div class="source-list">'+_sources(hub)+'</div><a href="/editorial-policy/">How GTASIX checks facts →</a></section></main>'
        )
        extra='<link rel="stylesheet" href="/assets/intent-hubs.css">'
        if hub["path"]=="/gta-6-help/":
            extra+='<script defer src="/assets/intent-help.js?v=20261120-gameplay"></script>'
        yield (hub["path"],hub["title"],hub["description"],body,ld,extra)

